use crate::ciphers::crc32::cipher::crc32_digest;
use crate::ciphers::crc32::keys::crc32_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one digest pass over `input_len` generated bytes.
pub fn crc32_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let seed = crc32_default_key();
    let watch = Stopwatch::start();
    let out = crc32_digest(&data, seed);
    std::hint::black_box(out);
    watch.elapsed_ns()
}
